head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.POPUP_URL_ISU = "/ui/lst/kindstk/ULDSTF05107.xml";   // 종류주식 종목선택 팝업 (원본 리터럴)
scwin.MKT_TP_KSE = "1";       // 유가증권시장
scwin.MKT_TP_KOSDAQ = "2";    // 코스닥시장

// 원본 : /kindstk/ULDSTF05102.gfm (상장심사 — 종류주식) — W-Craft 1차 변환 + API 적용 개발 사본(ui/ULDSTF05102/ULDSTF05102.xml)
/*
 * 화면 동작
 *  - 조회조건(증권구분·상장일 기간·법인·시장구분·종목)으로 종류주식 상장심사(신규상장) 목록을 조회한다.
 *  - 행을 더블클릭하면 그 건, [신규]는 아래 [유가증권]에서 고른 증권구분으로 신규상장관리 팝업을 연다.
 *    주권(ST)은 ULDSTF05103, 외국주권(FS)·주식예탁증권(DR)은 ULDSTF05104 다.
 *    팝업이 저장하고 닫히거나 창 닫기(X)로 닫히면 목록을 다시 조회하고 연 행을 다시 선택한다.
 *  - [법인 찾기]는 법인선택(ULDSTF05011), [종목 찾기]는 종목선택(ULDSTF05107) 팝업이다.
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF05102/ULDSTF05102.md (§번호는 이 문서의 절)
 */

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 29
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05102.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 29
 * @description 로딩 — 기간 콤보·기본 기간 → 기간 달력·조회 Enter 키 바인딩 → 시장 사용자 시장구분 고정 → 목록 조회. (원본 init — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 기간선택 콤보와 기본 기간(시작 19000101 ~ 종료 오늘+60일)
    $c.data.comboCbDataSetPeriod(sbx_periodTp);
    $c.lc.initSearchDate(cal_sDate, cal_eDate);

    // 2) 기간 달력 선후 검사(규칙 37)·조회 영역 Enter 키(규칙 22)
    $c.date.compareFromToDate(cal_sDate, cal_eDate, ["상장일 시작일", "상장일 종료일"]);
    $c.win.setEnterKeyEvent(grp_search, scwin.btn_search_onclick);

    // 3) 유가·코스닥 시장 사용자는 자기 시장으로 고정하고 시장구분 영역·열을 숨긴다
    const userMarket = $c.session.getUserInfo("market");
    if (userMarket === scwin.MKT_TP_KSE || userMarket === scwin.MKT_TP_KOSDAQ) {
        grd_list.setColumnVisible("trMktNm", false);
        rdo_spotIsuTrdMktTpCd.setValue(userMarket);
        panel_mkt_gubun.hide();
    }

    // 4) 목록 조회
    await scwin.selectList();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.btn_search_onclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description 조회 버튼 클릭 (조회 영역 Enter 키도 이 핸들러)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_search_onclick = async function (e) {
    try {
        await scwin.selectList();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05102.btn_search_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_excel_onclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description 엑셀다운로드 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_excel_onclick = async function (e) {
    try {
        await scwin.excelDown();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05102.btn_excel_onclick" });
    }
};

/**
 * @method
 * @name scwin.grd_list_oncelldblclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description 목록 행 더블클릭 — 그 건으로 신규상장관리 팝업을 연다. (원본 grd_list_oncelldblclick → fn_OpenDetail(row))
 * @param {Number} rowIndex 행 인덱스(화면 번호)
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns
 * @hidden N
 */
scwin.grd_list_oncelldblclick = async function (rowIndex, columnIndex, columnId) {
    try {
        await scwin.openDetail(rowIndex);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05102.grd_list_oncelldblclick" });
    }
};

/**
 * @method
 * @name scwin.btn_new_onclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description 신규 버튼 클릭 — [유가증권]을 골랐으면 신규로 신규상장관리 팝업을 연다. (원본 btn_new_onclick → fn_OpenDetail(-999))
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_new_onclick = async function (e) {
    try {
        await scwin.openNew();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05102.btn_new_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_coSearch_onclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description 법인 찾기(돋보기) 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_coSearch_onclick = async function (e) {
    try {
        await scwin.openCorpPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05102.btn_coSearch_onclick" });
    }
};

/**
 * @method
 * @name scwin.ibx_isurCd_onblur
 * @author Inswave
 * @date 2026. 10. 29
 * @description 법인코드 칸을 비우고 나가면 법인명도 비운다. (원본 ibx_isurCd_onblur)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.ibx_isurCd_onblur = function (e) {
    try {
        if ($c.util.isEmpty(ibx_isurCd.getValue())) {
            ibx_comNm.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05102.ibx_isurCd_onblur" });
    }
};

/**
 * @method
 * @name scwin.sbx_periodTp_onviewchange
 * @author Inswave
 * @date 2026. 10. 29
 * @description 기간선택 — 고른 기간으로 시작·종료일을 채운다(종료일 기준 역산, 종료일이 비면 오늘). (원본 sbx_periodTp_onviewchange)
 * @param {Object} info 변경 정보
 * @returns
 * @hidden N
 */
scwin.sbx_periodTp_onviewchange = function (info) {
    try {
        // 콤보 값(0~6)은 index 와 같고, 공통 함수는 숫자로 비교한다 — 원본 $c.cp.valueOfIndex 도 결국 index 를 돌려줬다(§9)
        $c.stf.setFromToDate(sbx_periodTp.getSelectedIndex(), cal_sDate, cal_eDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05102.sbx_periodTp_onviewchange" });
    }
};

/**
 * @method
 * @name scwin.btn_isuCdSearch_onclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description 종목 찾기(돋보기) 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_isuCdSearch_onclick = async function (e) {
    try {
        await scwin.openIsuPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05102.btn_isuCdSearch_onclick" });
    }
};

/**
 * @method
 * @name scwin.ibx_isuCd_onblur
 * @author Inswave
 * @date 2026. 10. 29
 * @description 종목코드 칸을 비우고 나가면 종목명도 비운다. (원본 ibx_isuCd_onblur)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.ibx_isuCd_onblur = function (e) {
    try {
        if ($c.util.isEmpty(ibx_isuCd.getValue())) {
            ibx_isuNm.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05102.ibx_isuCd_onblur" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectList
 * @author Inswave
 * @date 2026. 10. 29
 * @description 상장심사 목록 조회 — 조회조건은 dma_selectListReq 에 바인딩돼 있다. 건수를 적는다. (원본 fn_list_sync — §5.1)
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
 */
scwin.selectList = async function () {
    const sbmOptions = {
        id : "sbm_selectList",
        method : "get",
        action : "/api/listing/lstproc/kind/listing-review/select-list",
        ref : "dma_selectListReq",
        target : "dlt_selectListRes=body",
        gridview : "grd_list",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return false;    // 진행 중 조회가 있어 이번 호출은 건너뜀
    if (!result.responseJSON?.success) return false;    // 실패 안내는 공통 오류 핸들러

    tbx_totCnt.setValue(dlt_selectListRes.getRowCount());
    return true;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.openNew
 * @author Inswave
 * @date 2026. 10. 29
 * @description 신규 — [유가증권](증권구분)을 고르지 않았으면 안내하고 멈춘다. (원본 btn_new_onclick — §6.1)
 * @returns
 * @hidden N
 */
scwin.openNew = async function () {
    if ($c.util.isEmpty(sbx_newSecugrpId.getValue())) {
        await $c.win.alert($c.data.getMessage("com_req_select", "신규등록할 유가증권"));
        sbx_newSecugrpId.focus();
        return;
    }
    await scwin.openDetail(-1);
};

/**
 * @method
 * @name scwin.openDetail
 * @author Inswave
 * @date 2026. 10. 29
 * @description 신규상장관리 팝업을 data 로 열고 닫힐 때까지 기다린다 — 주권(ST)은 ULDSTF05103, 외국주권(FS)·주식예탁증권(DR)은 ULDSTF05104.
 * 팝업이 저장하고 닫혔거나(isSaved) 창 닫기(X)로 닫혔으면 목록을 다시 조회하고 연 행을 다시 선택한다. 키는 kindstk 공통 계약(05103/05104 절).
 * (원본 fn_OpenDetail + 팝업의 부모 직접 참조·fn_list_sync — §6.2, 가이드 §6.5)
 * @param {Number} rowIndex 목록 행 인덱스(화면 번호). 신규는 -1
 * @returns
 * @hidden N
 */
scwin.openDetail = async function (rowIndex) {
    let bzProcsNo = "";
    let secugrpId = "";
    let isurCd = "";
    let comNm = "";
    let listDd = "";

    if (rowIndex >= 0) {
        bzProcsNo = String(dlt_selectListRes.getCellData(rowIndex, "bzProcsNo") ?? "");
        secugrpId = String(dlt_selectListRes.getCellData(rowIndex, "secugrpId") ?? "");
        isurCd = String(dlt_selectListRes.getCellData(rowIndex, "isurCd") ?? "");
        comNm = String(dlt_selectListRes.getCellData(rowIndex, "comNm") ?? "");
        listDd = String(dlt_selectListRes.getCellData(rowIndex, "listDd") ?? "");
    } else {
        secugrpId = sbx_newSecugrpId.getValue();
    }

    let pageId = "";
    let height = 0;
    if (secugrpId === $c.lc.getGlbValue("SECUGRP_ID_ST")) {
        pageId = "ULDSTF05103";
        height = 935;
    } else if (secugrpId === $c.lc.getGlbValue("SECUGRP_ID_DR") || secugrpId === $c.lc.getGlbValue("SECUGRP_ID_FS")) {
        pageId = "ULDSTF05104";
        height = 980;
    } else {
        // 원본은 화면을 정하지 못해도 "undefined.xml" 로 열었다 — 증권구분이 ST·FS·DR 이 아니면 열지 않는다(§8 #4)
        await $c.win.alert("종류주식 신규상장관리를 열 수 없는 증권구분입니다.");
        return;
    }

    // 원본 data 의 rowPos(행 객체 — 팝업이 행 번호로 써서 결함)는 넘기지 않는다. 행 포커스 복원은 부모가 한다(§8 #3)
    const data = {
        bzProcsNo : bzProcsNo,                          // 원본 키 clickBzProcsNo → 계약 키 bzProcsNo (신규 "")
        newSecugrpId : sbx_newSecugrpId.getValue(),     // 신규 증권그룹 기본값
        isurCd : isurCd,
        comNm : comNm,
        listDd : listDd
    };
    const res = await $c.win.openPopup("/ui/lst/kindstk/" + pageId + ".xml",
        { id : pageId, popupName : $c.lc.getSecuGrpNm(secugrpId) + " 종류주식 신규상장관리", width : 1280, height : height, frameModal : "top" }, data);

    // 저장하고 닫힘 또는 창 닫기(X — 저장 여부를 모르므로 다시 조회) — kindstk 재조회 규약
    if (res?.isSaved !== true && res?.isCloseButtonClick !== true) return;
    if (!await scwin.selectList()) return;
    scwin.restoreRow(bzProcsNo, rowIndex);
};

/**
 * @method
 * @name scwin.restoreRow
 * @author Inswave
 * @date 2026. 10. 29
 * @description 다시 조회한 목록에서 팝업을 연 행을 다시 선택한다 — 업무처리번호가 같은 첫 행, 없으면 원래 행 번호. 신규는 선택하지 않는다.
 * (원본 05103 의 parentWin.grd_list.setFocusedCell(rowPos) — kindstk 공통 계약 「행 포커스 복원은 부모가」, §6.2)
 * @param {String} bzProcsNo 업무처리번호 (신규 "")
 * @param {Number} rowIndex 팝업을 열 때의 행 인덱스 (신규 -1)
 * @returns
 * @hidden N
 */
scwin.restoreRow = function (bzProcsNo, rowIndex) {
    const rowCount = dlt_selectListRes.getRowCount();
    if (rowIndex < 0 || rowCount === 0) return;

    let focusRow = -1;
    for (let i = 0; i < rowCount; i++) {
        if (String(dlt_selectListRes.getCellData(i, "bzProcsNo") ?? "") === bzProcsNo) {
            focusRow = i;
            break;
        }
    }
    if (focusRow < 0 && rowIndex < rowCount) focusRow = rowIndex;
    if (focusRow >= 0) grd_list.setFocusedCell(focusRow, 0);
};

/**
 * @method
 * @name scwin.openCorpPopup
 * @author Inswave
 * @date 2026. 10. 29
 * @description 법인 찾기 — 법인선택(ULDSTF05011)에서 고른 법인을 조회조건에 넣는다. 취소·창 닫기면 아무것도 하지 않는다. (원본 btn_coSearch_onclick — §6.3)
 * @returns
 * @hidden N
 */
scwin.openCorpPopup = async function () {
    // pcc 는 증권그룹ID 하나만 받는다 — 원본이 넘기던 "SLR"·시장구분은 쓰이지 않아 넘기지 않는다(§10 #3)
    const res = await $c.lc.popFindExamCorp(rdo_secugrpId.getValue());
    if ($c.util.isEmpty(res?.isurCd)) return;    // 취소·X 는 { isCloseButtonClick } — 원본은 그대로 undefined 를 넣었다(§8 #5)

    ibx_isurCd.setValue(String(res.isurCd));
    ibx_comNm.setValue(String(res.comNm ?? ""));
};

/**
 * @method
 * @name scwin.openIsuPopup
 * @author Inswave
 * @date 2026. 10. 29
 * @description 종목 찾기 — 종목선택(ULDSTF05107)을 data 로 열고, 고른 종목을 조회조건에 넣는다. 취소·창 닫기면 아무것도 하지 않는다.
 * 키는 kindstk 공통 계약(05107 절). (원본 fn_PopFindKindStkExamIsu — §6.4, 가이드 §6.5)
 * @returns
 * @hidden N
 */
scwin.openIsuPopup = async function () {
    // 원본이 넘기던 comNm 은 05107 이 쓰지 않아 뺀다(계약)
    const data = {
        isurCd : ibx_isurCd.getValue(),
        secugrpId : rdo_secugrpId.getValue(),
        mktTpCd : rdo_spotIsuTrdMktTpCd.getValue(),
        searchType : $c.lc.getGlbValue("SEARCH_TYP_SLR")    // 유가신규상장등록조회
    };
    const res = await $c.win.openPopup(scwin.POPUP_URL_ISU,
        { id : "ULDSTF05107", popupName : "종류주식 종목 선택", width : 800, height : 780, frameModal : "top", type : "pageFramePopup" }, data);
    // 원본 isCloseButtonClick === false 판정 + 대문자 ISU_CD 는 계약 반환(camelCase)과 맞지 않았다 — 필드로 판정(§8 #6)
    if ($c.util.isEmpty(res?.isuCd)) return;

    ibx_isuCd.setValue(String(res.isuCd));
    ibx_isuNm.setValue(String(res.isuNm ?? ""));
};

/**
 * @method
 * @name scwin.excelDown
 * @author Inswave
 * @date 2026. 10. 29
 * @description 목록을 엑셀로 내려받는다. 0건이면 안내한다. (원본 fn_excelDown — §6.5)
 * @returns
 * @hidden N
 */
scwin.excelDown = async function () {
    if (dlt_selectListRes.getRowCount() === 0) {
        await $c.win.alert($c.data.getMessage("com_search_0027"));
        return;
    }
    $c.data.downloadGridViewExcel(grd_list, {
        // 파일명 {menuId}_{이름}_{yyyyMMddHHmmss}.xlsx (전환 규칙 42)
        fileName : $c.win.getProgramId() + "_상장심사_" + $c.date.getServerDateTime("yyyyMMddHHmmss") + ".xlsx",
        sheetName : "리스트"
    });
};
